package com.tradeez.marketdata;

/**
 * Where a price series came from, and therefore what it may be used for.
 *
 * <p>This is deliberately a first-class domain property rather than a note in a README, because the
 * rules attached to it are not advisory:
 *
 * <ul>
 *   <li>{@link #SIMULATED} — generated by us. May drive detectors (injected ground truth is exactly
 *       what a detector unit test needs) but must <b>never</b> back a graded drill. Teaching
 *       pattern recognition from patterns we invented is circular: the learner would be learning
 *       the generator's artifacts, not the market's. DEC-034.</li>
 *   <li>{@link #IMPORTED_PRIVATE} — real data imported locally under someone's personal-use terms.
 *       Never leaves the machine, never served by a deployed instance. DEC-035.</li>
 *   <li>{@link #LICENSED_DEPLOYABLE} — real data we hold written permission to display. Nothing
 *       has this class yet, and nothing will until that permission exists. DEC-020.</li>
 * </ul>
 */
public enum DataClass {

	SIMULATED,
	IMPORTED_PRIVATE,
	LICENSED_DEPLOYABLE
}
